#include <vector>
#include <cstddef>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) {
        return 0;
    }

    // Basic safety check: need at least N*N entries.
    if ((A.size() / N) < N) {
        return 0;
    }

    int max_deg = 0;

    #pragma omp parallel for reduction(max : max_deg) schedule(static)
    for (size_t i = 0; i < N; ++i) {
        int degree = 0;
        const size_t row_offset = i * N;

        for (size_t j = 0; j < N; ++j) {
            degree += (A[row_offset + j] != 0) ? 1 : 0;
        }

        if (degree > max_deg) {
            max_deg = degree;
        }
    }

    return max_deg;
}
